import sys,json,re,html
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'src'))
import numpy as np
from cleartext.data import ROOT

run=ROOT/'runs/initial-20260924'
t=json.loads((run/'training.json').read_text());l=json.loads((run/'lexical.json').read_text());samples=json.loads((run/'pipeline_samples.json').read_text())
esc=lambda x:html.escape(str(x))
num=lambda x: '—' if x is None else f'{x:.3f}'
pct=lambda x:'—' if x is None else f'{x*100:.1f}%'
best=lambda key:next(r for r in t[key]['results'] if r['selected'])

def comparison(key):
    rows=[]
    for r in t[key]['results']:
        rows.append(f'<tr class="{"selected" if r["selected"] else ""}"><th scope="row">{esc(r["name"])}{" <span class=tag>selected</span>" if r["selected"] else ""}</th><td>{num(r["dev"]["mae"])}</td><td>{num(r["test"]["mae"])}</td><td>{num(r["test"]["spearman"])}</td></tr>')
    return '<div class="table-wrap"><table><thead><tr><th>Model</th><th>Dev MAE ↓</th><th>Test MAE ↓</th><th>Test rank ρ ↑</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'

def scatter():
    rows=t['word']['test_predictions'];width=540;height=245;x0=42;y0=204;w=450;h=175
    circles=''.join(f'<circle cx="{x0+r["label"]*w:.2f}" cy="{y0-r["prediction"]*h:.2f}" r="2.2"><title>Human {r["label"]:.2f}, predicted {r["prediction"]:.2f}</title></circle>' for r in rows[::3])
    ticks=''.join(f'<text x="{x0+a*w}" y="222" text-anchor="middle">{a:g}</text><text x="32" y="{y0-a*h+4}" text-anchor="end">{a:g}</text>' for a in [0,.25,.5,.75,1])
    return f'<svg class="scatter" viewBox="0 0 {width} {height}" role="img" aria-label="Predicted versus human word difficulty, every third test example in source order"><path class="axes" d="M{x0} 22 V{y0} H492"/><path class="ideal" d="M{x0} {y0} L492 29"/>{ticks}<g class="dots">{circles}</g><text x="270" y="242" text-anchor="middle">Human difficulty</text><text x="44" y="14">Predicted difficulty</text></svg>'

word_improve=(best('word')['test']['mae']/next(r for r in t['word']['results'] if r['name']=='Frequency')['test']['mae'])
errors=np.asarray([r['absolute_error'] for r in t['word']['test_predictions']])-np.asarray([r['absolute_error'] for r in t['context']['test_predictions']])
rng=np.random.default_rng(4701);boot=np.array([np.mean(rng.choice(errors,len(errors),replace=True)) for _ in range(1000)])
ci=np.quantile(boot,[.025,.975])
fit=l['context_fit']
fitrows=''.join(f'<tr><th scope="row">{esc(r["name"])}</th><td>{num(r["dev"]["auc"])}</td><td>{num(r["test"]["auc"])}</td><td>{num(r["test"]["f1"])}</td></tr>' for r in fit['results'])
names={'unchanged':'Keep original','dictionary':'Dictionary + frequency','learned':'Learned difficulty','context':'+ context model','guarded':'+ preservation checks'}
tsarrows=''.join(f'<tr><th scope="row">{names[r["name"]]}</th><td>{pct(r["official_precision1"])}</td><td>{pct(r["edit_rate"])}</td><td>{pct(r["edited_gold_match"])}</td></tr>' for r in l['tsar'])
proberows=''.join(f'<tr><th scope="row">{esc(r["category"])}</th><td>{esc(r["candidate"])}</td><td class="{"good" if r["pass"]==r["expected_pass"] else "bad"}">{"Accepted" if r["pass"] else "Rejected"}{" · missed error" if r["pass"] and not r["expected_pass"] else ""}</td></tr>' for r in l['guardrail_probes'])
counts=lambda key:', '.join(f'{v:,} {k}' for k,v in t[key]['counts'].items())
sources=[('CompLex','https://github.com/MMU-TDMLab/CompLex','CC BY 4.0; word ratings'),('CEFR-SP','https://github.com/yukiar/CEFR-SP','Wiki-Auto: CC BY-SA 3.0; SCoRE: CC BY-NC-SA 4.0; public sources only'),('SWORDS','https://github.com/p-lambda/swords','CC BY 3.0 US; contextual substitutes'),('TSAR 2022','https://github.com/LaSTUS-TALN-UPF/TSAR-2022-Shared-Task','Data: CC BY-NC-SA 4.0; evaluator: AGPL 3.0'),('wordfreq','https://github.com/rspeer/wordfreq','Frequency features; see project attribution'),('CMUdict','https://github.com/cmusphinx/cmudict','Pronunciation and syllable features'),('WordNet','https://wordnet.princeton.edu/','Sense groups and candidate synonyms'),('Brown corpus','https://www.nltk.org/book/ch02.html','Bigram counts via NLTK'),('spaCy English small pipeline','https://spacy.io/models/en#en_core_web_sm','POS, morphology, dependency parsing, entities; no transformer'),('LemmInflect','https://github.com/bjascob/LemmInflect','Candidate inflection')]
sourcehtml=''.join(f'<li><a href="{url}">{name}</a> <span class="muted">{esc(note)}</span></li>' for name,url,note in sources)

def stratified(rows,n):
    ordered=sorted(rows,key=lambda r:r['label']);idx=np.linspace(0,len(rows)-1,n).round().astype(int)
    selected=[ordered[i] for i in idx]
    np.random.default_rng(4701).shuffle(selected)
    return selected

review_words=[{'id':'word-'+r['id'],'text':r['text'],'target':r['token'],'human':r['label'],'prediction':r['prediction'],'domain':r['corpus']} for r in stratified(t['word']['test_predictions'],20)]
review_sentences=[{'id':'sentence-'+r['id'],'text':r['text'],'human':r['label'],'raters':[r['a'],r['b']],'prediction':r['prediction'],'domain':r['corpus']} for r in stratified(t['sentence']['test_predictions'],12)]
review_replacements=[]
for r in l['review']:
    review_replacements.append({k:r[k] for k in ['id','domain','original','target','replacement','output','changed','reason']})
for s in samples:
    if s['edit']:
        s['edit']={k:s['edit'][k] for k in ['target','replacement','reason']}
payload={'words':review_words,'sentences':review_sentences,'replacements':review_replacements,'samples':samples,'run':'initial-20260924'}

